import base64

encoded = ""

base64_dec = base64.b64decode(encoded)

xor_key = [175, 30, 27, 5, 85, 73, 115, 174]

result = b""

for i in range(len(base64_dec)):
	decoded = base64_dec[i] ^ xor_key[i%8]
	result += decoded.to_bytes(1, byteorder="big")

with open("decoded2.zip", "wb") as f:
	f.write(result)